INSERT INTO `Settings` (`id`, `key`, `value`, `updatedAt`) VALUES ('cmtha93rb003fq9amf4sou3kl', 'about_intro', 'PAN Mandarga est une maison de mode sénégalaise née d''un amour profond pour le savoir-faire local et l''élégance contemporaine.', '2026-09-01 17:14:35.885');
INSERT INTO `Settings` (`id`, `key`, `value`, `updatedAt`) VALUES ('cmtha93rc003gq9amhmritbs7', 'about_story', 'Chaque pièce est pensée pour célébrer le corps, la matière et le geste. Du choix du tissu à la couture finale, PAN Mandarga cultive une exigence discrète : celle de vêtements qui durent, qui flattent, qui parlent. S''habiller c''est s''aimer — c''est l''idée simple qui guide chacune de nos créations.', '2026-09-01 17:14:35.887');
